    loadImg("hole", "https://img.remit.ee/api/file/BQACAgUAAyEGAASHRsPbAAEY-UtqexQhRSBJFnJcpy6PIhuZjKvr5gACLikAAmsm2FfztMHk5n0xjT0E.png");
