                const imgMatch = rawReply.match(/【(?:配图描述|画面描述|配图)】\s*([\s\S]*?)$/i);
                if (textMatch && textMatch[1]) momentText = textMatch[1].trim();
                if (imgMatch && imgMatch[1]) imagePrompt = imgMatch[1].trim();
